	for name, value := range required {
		if strings.TrimSpace(value) == "" {
			return fmt.Errorf("%s cannot be empty", name)
		}
	}
	wantProfileID := strings.Join([]string{manifest.EngineID, manifest.OS, manifest.Architecture}, "-")
