func resolveRuntime(installRoot, relative string) (string, error) {
	root, err := filepath.Abs(installRoot)
	if err != nil {
		return "", fmt.Errorf("resolve install_root %q: %w", installRoot, err)
	}
	path, err := filepath.Abs(filepath.Join(root, relative))
	if err != nil {
		return "", fmt.Errorf("resolve runtime %q: %w", relative, err)
	}
	rel, err := filepath.Rel(root, path)
	if err != nil || rel == "." || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return "", fmt.Errorf("runtime %q resolves outside install_root", relative)
	}
	return path, nil
}

func hashExecutable(path string) (string, error) {
	file, err := os.Open(path)
	if err != nil {
		return "", fmt.Errorf("open engine executable %q: %w", path, err)
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return "", fmt.Errorf("stat engine executable %q: %w", path, err)
	}
	if !info.Mode().IsRegular() {
		return "", fmt.Errorf("engine executable %q is not a regular file", path)
	}
	hasher := sha256.New()
	if _, err := io.Copy(hasher, file); err != nil {
		return "", fmt.Errorf("hash engine executable %q: %w", path, err)
	}
	return hex.EncodeToString(hasher.Sum(nil)), nil
}

